from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity: int, ttl: float, clock):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self._cache = OrderedDict()
        self._stats = {"hits": 0, "misses": 0, "evictions": 0, "expirations": 0}

    def _now(self) -> float:
        return self.clock()

    def _is_expired(self, expiry_time: float) -> bool:
        return self._now() >= expiry_time

    def _remove_expired_keys(self):
        """Remove all expired keys and update expirations count."""
        expired_keys = []
        for key in self._cache:
            if self._is_expired(self._cache[key][1]):
                expired_keys.append(key)
        for key in expired_keys:
            del self._cache[key]
            self._stats["expirations"] += 1

    def _evict_lru(self):
        """Evict least recently used entry and increment eviction counter."""
        if self._cache:
            self._cache.popitem(last=False)
            self._stats["evictions"] += 1

    def put(self, key, value):
        if self.capacity == 0:
            return

        now = self._now()
        self._remove_expired_keys()

        if key in self._cache:
            _, _ = self._cache[key]
            self._cache[key] = (value, now + self.ttl)
            self._cache.move_to_end(key)
        else:
            if len(self._cache) >= self.capacity:
                self._evict_lru()
            self._cache[key] = (value, now + self.ttl)

    def get(self, key, default=None):
        if key not in self._cache:
            self._stats["misses"] += 1
            return default

        value, expiry_time = self._cache[key]

        if self._is_expired(expiry_time):
            del self._cache[key]
            self._stats["expirations"] += 1
            self._stats["misses"] += 1
            return default

        self._cache.move_to_end(key)
        self._stats["hits"] += 1
        return value

    def __len__(self) -> int:
        now = self._now()
        return sum(1 for _, (v, e) in self._cache.items() if not self._is_expired(e))

    def stats(self):
        return {
            "hits": self._stats["hits"],
            "misses": self._stats["misses"],
            "evictions": self._stats["evictions"],
            "expirations": self._stats["expirations"]
        }
