import re

def parse_duration(s: str) -> int:
    if not s or not s.strip():
        raise ValueError("Empty or blank string")

    # Remove all whitespace to simplify parsing
    s_normalized = s.strip().replace(' ', '')

    # If no digits found, ensure no stray characters remain
    if not re.search(r'\d', s_normalized):
        raise ValueError("Invalid format")

    # Extract all tokens matching pattern: digits followed by single h/m/s (case-insensitive)
    tokens = re.findall(r'\d+[hmsHMS]', s_normalized)

    if not tokens:
        # Check if digits exist but no unit follows
        if re.search(r'\d', s_normalized):
            raise ValueError("Number without unit")
        raise ValueError("Empty or blank string")

    # Validate that entire normalized string is fully consumed by tokens
    remaining = re.sub(r'\d+[hmsHMS]', '', s_normalized)
    if remaining:
        raise ValueError("Invalid format")

    total_seconds = 0
    seen_units: set[str] = set()
    last_unit_index: int | None = None
    order = {'h': 0, 'm': 1, 's': 2}

    for token in tokens:
        unit_char = token[-1].lower()
        number = int(token[:-1])

        if unit_char not in order:
            raise ValueError("Unknown unit")

        if unit_char in seen_units:
            raise ValueError("Repeated unit")
        seen_units.add(unit_char)

        current_index = order[unit_char]

        if last_unit_index is not None and current_index <= last_unit_index:
            raise ValueError("Units out of order")

        if unit_char == 'h':
            total_seconds += number * 3600
        elif unit_char == 'm':
            total_seconds += number * 60
        elif unit_char == 's':
            total_seconds += number

        last_unit_index = current_index

    return total_seconds
